import {index,displayVoxelFromPlane,displayRowIndex,displayPlanePixel,planeAspect,localEdit,history,autoSeed} from './algorithm.mjs?v=0.4.10';
import {filesFromDrop,describeInput} from './drop-files.mjs?v=0.4.10';
import {inputGeneration} from './input-generation.mjs?v=0.4.10';
const $=id=>document.getElementById(id),names=['','Intraparenchymal','Intraventricular','Subarachnoid','Subdural','Epidural'],colors=[[0,0,0],[255,78,84],[79,172,255],[255,194,57],[184,109,252],[66,225,166]];
const inputGate=inputGeneration();
let volume=null,mask=null,edits=null,worker=null,preview=null,holding=null,navigating=null,cross=[0,0,0];const canvases=['axial','coronal','sagittal'];
function status(text){$('status').textContent=text;}
function action(text){$('action').textContent=text;}
function clearVolume(){volume=mask=edits=preview=null;if(holding)clearInterval(holding.timer);holding=navigating=null;action('');for(const plane of canvases){const canvas=$(plane);canvas.width=canvas.height=1;canvas.getContext('2d').clearRect(0,0,1,1);}$('volumes').textContent='No volume loaded.';$('warnings').hidden=true;$('warnings').textContent='';}
function setVolume(v){volume=v;mask=new Uint8Array(v.data.length);edits=history(mask,v);cross=v.dims.map(n=>Math.floor(n/2));for(const [id,dim] of [['x',0],['y',1],['z',2]]){$(id).max=v.dims[dim]-1;$(id).value=cross[dim];}const warnings=v.warnings||[],approximate=v.reductionFactor>1;$('warnings').hidden=!warnings.length;$('warnings').textContent=warnings.join(' ');$('volumeHeading').textContent=approximate?'Approximate volumes on reduced grid (mL)':'Source-grid volumes (mL)';status((v.synthetic?'Synthetic demo':approximate?'Reduced CT grid · approximate':'CT source grid')+' · '+v.dims.join(' × ')+' · Float32 · local only');action($('interaction-nav').checked?'Navigate mode: to mark blood, select Segment and Local CT seed above, then click within the hemorrhage.':'Segment mode: select Local CT seed and click within 30–100 HU blood to start.');draw();renderVolumes();}
function synthetic(){inputGate.begin();worker?.terminate();worker=null;$('series').hidden=$('load').hidden=true;const dims=[64,64,32],data=new Float32Array(dims.reduce((a,b)=>a*b,1));for(let z=0;z<dims[2];z++)for(let y=0;y<dims[1];y++)for(let x=0;x<dims[0];x++){
 const r=Math.hypot((x-32)/25,(y-32)/26,(z-16)/13),lesion=Math.hypot((x-26)/7,(y-30)/5,(z-17)/5);data[index(dims,x,y,z)]=r>1?-950:lesion<1?68:r>.88?350:27+4*Math.sin(x*.27+y*.18+z*.43);
 }setVolume({dims,data,matrix:[.8,0,0,0,.8,0,0,0,1.5],origin:[0,0,0],synthetic:true});}
function draw(){if(!volume)return;const previewSet=preview?new Set(preview):null;for(const plane of canvases){const canvas=$(plane),dims=volume.dims,w=plane==='sagittal'?dims[1]:dims[0],h=plane==='axial'?dims[1]:dims[2],ctx=canvas.getContext('2d');canvas.width=w;canvas.height=h;canvas.style.aspectRatio=String(planeAspect(volume,plane));const image=ctx.createImageData(w,h),level=Number($('level').value)||60,width=Math.max(1,Number($('width').value)||160),selected=Number($('label').value);
 for(let b=0;b<h;b++){const [row,stride]=displayRowIndex(volume,plane,b,cross[plane==='axial'?2:plane==='coronal'?1:0]);for(let a=0;a<w;a++){const i=row+a*stride,out=(b*w+a)*4,hu=volume.data[i],gray=Number.isFinite(hu)?Math.round(Math.max(0,Math.min(255,255*(hu-(level-width/2))/width))):0,lab=previewSet?.has(i)?(holding?.tool==='shrink'?0:selected):mask[i],c=colors[lab];image.data[out]=lab?Math.round(gray*.48+c[0]*.52):gray;image.data[out+1]=lab?Math.round(gray*.48+c[1]*.52):gray;image.data[out+2]=lab?Math.round(gray*.48+c[2]*.52):gray;image.data[out+3]=255;}}
 ctx.putImageData(image,0,0);const [cx,cy]=displayPlanePixel(volume,plane,cross);ctx.strokeStyle='#30f2d6';ctx.lineWidth=Math.max(1,w/130);ctx.beginPath();ctx.moveTo(cx+.5,0);ctx.lineTo(cx+.5,h);ctx.moveTo(0,cy+.5);ctx.lineTo(w,cy+.5);ctx.stroke();}
}
function renderVolumes(){if(!volume)return;const m=edits.volumes(),prefix=volume.reductionFactor>1?'≈':'';$('volumes').replaceChildren(...names.slice(1).map((name,n)=>{const span=document.createElement('span');span.style.color=`rgb(${colors[n+1].join(',')})`;span.textContent=name+': '+prefix+(m[n+1]||0).toFixed(3);return span;}));const total=document.createElement('strong');total.textContent='Total: '+prefix+m.total.toFixed(3);$('volumes').append(total);
}
function point(e,plane){const rect=e.currentTarget.getBoundingClientRect(),a=Math.max(0,Math.min(e.currentTarget.width-1,Math.floor((e.clientX-rect.left)*e.currentTarget.width/rect.width))),b=Math.max(0,Math.min(e.currentTarget.height-1,Math.floor((e.clientY-rect.top)*e.currentTarget.height/rect.height)));return displayVoxelFromPlane(volume,plane,a,b,cross[plane==='axial'?2:plane==='coronal'?1:0]);}
function setCross(xyz,redraw=true){if(cross.every((v,i)=>v===xyz[i]))return;cross=xyz;for(const [id,i] of [['x',0],['y',1],['z',2]])$(id).value=cross[i];if(redraw)draw();}
function updatePreview(){if(!holding||!volume)return;const elapsed=(performance.now()-holding.start)/800,radius=Number($('radius').value)+Math.min(24,elapsed*2);preview=localEdit(volume,mask,holding.xyz,holding.label,holding.tool,radius,1);draw();}
for(const plane of canvases){const c=$(plane);c.addEventListener('contextmenu',e=>e.preventDefault());c.addEventListener('pointerdown',e=>{
 if(!volume||e.button!==0&&e.button!==2)return;e.preventDefault();const xyz=point(e,plane);const editPreview=$('interaction-segment').checked&&e.button===0&&!e.shiftKey;setCross(xyz,!editPreview);
 if($('interaction-nav').checked||e.button===2||e.shiftKey){action('3D cursor moved. To mark blood, select Segment and Local CT seed.');navigating=e.pointerId;c.setPointerCapture(e.pointerId);return;}
 const tool=$('tool').value,label=Number($('label').value);
 if(tool==='seed'){const radius=Number($('radius').value),hits=autoSeed(volume,xyz,30,100,radius);if(hits.length>200000){action('Local seed exceeds 200,000 grid voxels: reduce Radius.');draw();return;}const added=edits.commit(hits.filter(i=>mask[i]===0),label);action(added?`Local seed: ${added} grid voxels within ${radius} mm (30–100 HU). Review all three views; this is not an automatic hemorrhage classifier.`:'No new voxels: click inside 30–100 HU blood, or check the selected mode and label.');draw();renderVolumes();return;}
 holding={xyz,tool,label,start:performance.now(),pointer:e.pointerId};c.setPointerCapture(e.pointerId);updatePreview();holding.timer=setInterval(updatePreview,150);
});c.addEventListener('pointermove',e=>{if(navigating===e.pointerId&&e.buttons)setCross(point(e,plane));});c.addEventListener('pointerup',e=>{
 if(navigating===e.pointerId){setCross(point(e,plane));navigating=null;return;}
 if(!holding||holding.pointer!==e.pointerId)return;clearInterval(holding.timer);updatePreview();const changes=preview||[];const changed=edits.commit(changes,holding.tool==='grow'?holding.label:0);action(changed?`Local ${holding.tool}: ${changed} grid voxels. Review all three views.`:`No local change: start with a seed, then click 30–100 HU blood beside its contour (grow) or inside its surface (shrink).`);holding=null;preview=null;draw();renderVolumes();
});c.addEventListener('pointercancel',e=>{if(navigating===e.pointerId)navigating=null;if(holding?.pointer===e.pointerId){clearInterval(holding.timer);holding=null;preview=null;draw();}});}
for(const [id,dim] of [['x',0],['y',1],['z',2]])$(id).addEventListener('input',e=>{cross[dim]=Number(e.target.value);draw();});
for(const id of ['interaction-nav','interaction-segment'])$(id).addEventListener('change',()=>{if(volume)action($('interaction-nav').checked?'Navigate mode: clicks and drags move the 3D cursor only.':'Segment mode: choose Local CT seed and click within blood; Radius limits the 3D selection.');});
for(const id of ['level','width','label'])$(id).addEventListener('input',draw);$('radius').addEventListener('input',()=>{$('radiusText').textContent=$('radius').value+' mm';updatePreview();});$('undo').onclick=()=>{if(edits?.undo()){draw();renderVolumes();}};$('redo').onclick=()=>{if(edits?.redo()){draw();renderVolumes();}};$('demo').onclick=synthetic;
function scan(files,isDirectory=false){inputGate.begin();if(!files.length)return;clearVolume();worker?.terminate();worker=new Worker('./io-worker.js?v=0.4.10');const current=worker,input=describeInput(files,isDirectory);status('Сканирование · '+input);$('series').hidden=$('load').hidden=true;worker.onerror=e=>{if(worker===current)status('Worker failure ('+input+'): '+e.message);};worker.onmessage=({data})=>{if(worker!==current)return;if(data.type==='error'){status('Measurement blocked [v0.4.5; '+input+']: '+data.message);return;}if(data.type==='groups'){const select=$('series');select.replaceChildren(...data.groups.map(g=>{const o=document.createElement('option');o.value=g.key;o.textContent=g.name+' · '+g.modality+' · '+g.frames+' slices · '+g.dims.join('×');return o;}));if(data.groups.length===1){select.hidden=$('load').hidden=true;status('One series found · decoding full CT stack…');worker.postMessage({type:'build',key:data.groups[0].key});}else{select.hidden=$('load').hidden=false;status('Choose a series ('+data.groups.length+' found; '+data.skipped+' skipped).');}}if(data.type==='volume')setVolume(data.volume);if(data.type==='progress')status(data.text+' '+Math.round(data.fraction*100)+'%');};worker.postMessage({type:'scan',slot:'ct',files:Array.from(files)});}
$('files').onchange=e=>scan(e.target.files);$('folder').onchange=e=>scan(e.target.files,true);$('load').onclick=()=>{if(!worker)return;clearVolume();status('Decoding full CT stack…');worker.postMessage({type:'build',key:$('series').value});};
document.addEventListener('dragover',e=>e.preventDefault());
document.addEventListener('drop',async e=>{
 e.preventDefault();const token=inputGate.begin();
 worker?.terminate();worker=null;clearVolume();$('series').hidden=$('load').hidden=true;status('Reading dropped input…');
 try{const isDirectory=Array.from(e.dataTransfer.items||[]).some(item=>item.webkitGetAsEntry?.()?.isDirectory),awaitedFiles=await filesFromDrop(e.dataTransfer);if(inputGate.current(token))scan(awaitedFiles,isDirectory);}
 catch(error){if(inputGate.current(token))status('Не удалось прочитать перетащенную папку: '+error.message);}
});
